#include <LiquidCrystal.h>
#include <math.h>

// ============================================
// SMART GREENHOUSE - PID TEMPERATURE CONTROL
// Arduino UNO + Proteus
// ============================================

// LCD connections
LiquidCrystal lcd(12, 11, 5, 4, 3, 2);

// Pins
const byte LM35_PIN  = A0;
const byte HEATER_PIN = 9;
const byte FAN_PIN    = 10;

// Temperature settings
const double SETPOINT = 25.0;

// PID parameters: initial simulation values
double Kp = 30.0;
double Ki = 0.25;
double Kd = 2.0;

// PID variables
double integral = 0.0;
double previousError = 0.0;

// Initial and simulated temperatures
double ambientTemperature = 0.0;
double simulatedTemperature = 0.0;

// PID output
int heaterPWM = 0;
int fanPWM = 0;

// Timing
unsigned long previousControlTime = 0;
unsigned long previousDisplayTime = 0;

const unsigned long CONTROL_INTERVAL = 100;
const unsigned long DISPLAY_INTERVAL = 300;

// Thermal model parameters
// These are illustrative simulation parameters,
// not measured physical properties.
const double HEATING_RATE = 0.12;
const double FAN_COOLING_RATE = 0.15;
const double PASSIVE_LOSS = 0.015;

// ============================================
// Read LM35
// ============================================

double readLM35() {
  int rawValue = analogRead(LM35_PIN);

  double voltage = rawValue * (5.0 / 1023.0);

  // LM35: approximately 10 mV per degree C
  return voltage * 100.0;
}

// ============================================
// Setup
// ============================================

void setup() {
  pinMode(HEATER_PIN, OUTPUT);
  pinMode(FAN_PIN, OUTPUT);

  analogWrite(HEATER_PIN, 0);
  analogWrite(FAN_PIN, 0);

  lcd.begin(16, 2);
  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("Greenhouse PID");

  lcd.setCursor(0, 1);
  lcd.print("Initializing");

  delay(1500);

  // Read the manually selected LM35 temperature
  ambientTemperature = readLM35();

  // Start the thermal model from that temperature
  simulatedTemperature = ambientTemperature;

  previousControlTime = millis();
  previousDisplayTime = millis();

  lcd.clear();
}

// ============================================
// Main loop
// ============================================

void loop() {
  unsigned long now = millis();

  // ------------------------------------------
  // PID CONTROL
  // ------------------------------------------

  if (now - previousControlTime >= CONTROL_INTERVAL) {

    double dt =
      (now - previousControlTime) / 1000.0;

    previousControlTime = now;

    // Error: desired temperature - current temperature
    double error = SETPOINT - simulatedTemperature;

    // Integral
    integral += error * dt;
    integral = constrain(integral, -100.0, 100.0);

    // Derivative
    double derivative = 0.0;

    if (dt > 0.0) {
      derivative = (error - previousError) / dt;
    }

    previousError = error;

    // PID output
    double pidOutput =
      Kp * error +
      Ki * integral +
      Kd * derivative;

    pidOutput = constrain(pidOutput, -255.0, 255.0);

    // Heating below the setpoint
    if (error > 0.15) {

      heaterPWM = (int)pidOutput;
      heaterPWM = constrain(heaterPWM, 0, 255);

      fanPWM = 0;
    }

    // Cooling above the setpoint
    else if (error < -0.15) {

      heaterPWM = 0;

      fanPWM = (int)(-pidOutput);
      fanPWM = constrain(fanPWM, 0, 255);
    }

    // Near the setpoint
    else {

      heaterPWM = 0;
      fanPWM = 0;
      integral = 0.0;
    }

    // Apply outputs
    analogWrite(HEATER_PIN, heaterPWM);
    analogWrite(FAN_PIN, fanPWM);

    // ----------------------------------------
    // THERMAL PLANT SIMULATION
    // ----------------------------------------

    double heaterEffect =
      HEATING_RATE * ((double)heaterPWM / 255.0);

    double fanEffect =
      FAN_COOLING_RATE * ((double)fanPWM / 255.0);

    // Passive heat loss toward ambient temperature
    double passiveEffect =
      PASSIVE_LOSS *
      (simulatedTemperature - ambientTemperature);

    // Temperature changes due to the actuators
    simulatedTemperature +=
      (heaterEffect - fanEffect - passiveEffect) * dt;

    // Prevent unrealistic numerical values
    simulatedTemperature =
      constrain(simulatedTemperature, -20.0, 100.0);
  }

  // ------------------------------------------
  // LCD DISPLAY
  // ------------------------------------------

  if (now - previousDisplayTime >= DISPLAY_INTERVAL) {

    previousDisplayTime = now;

    lcd.setCursor(0, 0);
    lcd.print("Temp:");
    lcd.print(simulatedTemperature, 1);
    lcd.write(byte(223));
    lcd.print("C   ");

    lcd.setCursor(0, 1);

    if (heaterPWM > 0) {
      lcd.print("HEAT PWM:");
      lcd.print(heaterPWM);
      lcd.print("   ");
    }
    else if (fanPWM > 0) {
      lcd.print("FAN PWM:");
      lcd.print(fanPWM);
      lcd.print("    ");
    }
    else {
      lcd.print("AT SETPOINT    ");
    }
  }
}
